parameters.text:
=Hi, you are a helpful job matcher. Analyze the resume and job description to determine a match score. Do NOT write a cover letter. Your output MUST be a valid JSON object matching this structure exactly:

{
  "airtable_dashboard": {
    "summary_metrics": [
      { "title": "Total Jobs Analyzed", "calculation_logic": "Count of all records pulled", "timestamp_ref": "03:10" },
      { "title": "Average Final Job Score", "calculation_logic": "Mean of all Final Scores", "timestamp_ref": "03:15" },
      { "title": "Top Scoring Jobs", "calculation_logic": "Count of jobs exceeding threshold", "timestamp_ref": "03:19" }
    ],
    "visualizations": [
      { "graph_title": "Open Roles by Company", "graph_type": "Bar Chart", "axes": { "x_axis": "Company Name", "y_axis": "Count of Job IDs" }, "timestamp_ref": "03:22" },
      { "graph_title": "Openings by Experience Level", "graph_type": "Bar or Pie Chart", "parameters": ["Junior", "Middle", "Senior", "Director"], "timestamp_ref": "03:27" },
      { "graph_title": "Jobs Posted per Day", "graph_type": "Timeline", "axes": { "x_axis": "Publication Date", "y_axis": "Count of Records" }, "timestamp_ref": "03:39" },
      { "graph_title": "Top Ranking Skills", "graph_type": "Word Cloud", "parameters": ["Python", "SQL", "AWS", "Generative AI"], "timestamp_ref": "03:47" }
    ],
    "data_table_schema": {
      "metadata_fields": ["Job ID", "Publication Date", "LinkedIn Company Name", "Job Title", "Job Link"],
      "categorization_fields": ["Experience Level", "Required Skills", "Responsibilities", "Company Benefits"],
      "scoring_fields_0_100": ["Skills Score", "Responsibilities Score", "Experience Score", "Benefits Score"],
      "final_output_fields": ["Final Job Score (weighted average)", "Remote/Flexible Work status"],
      "data_source_pipeline": "LinkedIn > RSS.app > n8n > Airtable",
      "timestamp_ref": "02:19"
    }
  }
}

job_description: {{ $json.description }}
my_resume: {{ $('Extract Text from Resume').item.json.text }}
